package adris.altoclef.eventbus;

import java.util.*;
import java.util.function.Consumer;

/** Snapshot dispatch: callbacks run outside the topic lock and scoped subscriptions retire at close. */
public class EventBus {
    private static final Map<Class<?>, List<Subscription<?>>> topics = new HashMap<>();

    public static <T> void publish(T event) {
        Objects.requireNonNull(event);
        Class<?> type = event.getClass();
        List<Subscription<?>> snapshot;
        synchronized (topics) {
            prune(type);
            snapshot = List.copyOf(topics.getOrDefault(type, List.of()));
        }
        try {
            for (Subscription<?> subscription : snapshot) {
                if (!subscription.shouldDelete()) deliver(subscription, event);
            }
        } finally {
            synchronized (topics) { prune(type); }
        }
    }

    @SuppressWarnings("unchecked")
    private static <T> void deliver(Subscription<?> subscription, T event) {
        ((Subscription<T>) subscription).accept(event);
    }

    private static void prune(Class<?> type) {
        List<Subscription<?>> listeners = topics.get(type);
        if (listeners == null) return;
        listeners.removeIf(Subscription::shouldDelete);
        if (listeners.isEmpty()) topics.remove(type);
    }

    public static <T> Subscription<T> subscribe(Class<T> type, Consumer<T> consumeEvent) {
        Objects.requireNonNull(type);
        Subscription<T> subscription = new Subscription<>(consumeEvent);
        synchronized (topics) { topics.computeIfAbsent(type, ignored -> new ArrayList<>()).add(subscription); }
        return subscription;
    }

    public static <T> void unsubscribe(Subscription<T> subscription) {
        if (subscription == null) return;
        subscription.delete();
        synchronized (topics) {
            for (var iterator = topics.entrySet().iterator(); iterator.hasNext();) {
                var listeners = iterator.next().getValue();
                listeners.removeIf(item -> item == subscription || item.shouldDelete());
                if (listeners.isEmpty()) iterator.remove();
            }
        }
    }
}

